BEGIN;
-- Preserve historical decisions; existing workspaces need a fresh assessment
-- because their previous forecast was generated by a different model.
ALTER TABLE web_workspaces ADD COLUMN IF NOT EXISTS forecast_version integer NOT NULL DEFAULT 1;
WITH changed AS (
    UPDATE web_workspaces SET revision = gen_random_uuid(), forecast_version = 2
    WHERE forecast_version = 1 RETURNING id, revision
)
INSERT INTO web_revisions (id, workspace_id, liquidity_request, investment_request)
SELECT revision, id, gen_random_uuid(), gen_random_uuid() FROM changed;
ALTER TABLE web_workspaces ALTER COLUMN forecast_version SET DEFAULT 2;
COMMIT;
